 "content": "def transform(grid):
    """Return the 3x3 connected nonzero pattern containing exactly 3 colors."""
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if len({grid[y][x] for y, x in cells}) == 3:
                top = min(y for y, _ in cells)
                bottom = max(y for y, _ in cells)
                left = min(x for _, x in cells)
                right = max(x for _, x in cells)
                return [row[left:right + 1] for row in grid[top:bottom + 1]]
    raise ValueError("No three-color nonzero component found")
